def circularGameLosers(n: int, k: int) -> list[int]:
    received = {0}
    current = 0
    step = 1

    while True:
        current = (current + step * k) % n
        if current in received:
            break
        received.add(current)
        step += 1

    return [friend + 1 for friend in range(n) if friend not in received]
