from collections import deque


def solve():
    input = sys.stdin.buffer.readline
    H, W = map(int, input().split())
    grid = [input().strip() for _ in range(H)]
    n = H * W

    # Mark empty cells adjacent to a magnet.
    dangerous = bytearray(n)
    for r in range(H):
        for c in range(W):
            if grid[r][c] == ord('#'):
                if r > 0:
                    dangerous[(r - 1) * W + c] = 1
                if r + 1 < H:
                    dangerous[(r + 1) * W + c] = 1
                if c > 0:
                    dangerous[r * W + c - 1] = 1
                if c + 1 < W:
                    dangerous[r * W + c + 1] = 1

    seen = bytearray(n)
    answer = 1

    for r in range(H):
        for c in range(W):
            start = r * W + c
            if grid[r][c] == ord('#') or dangerous[start] or seen[start]:
                continue

            queue = deque([start])
            seen[start] = 1
            component_size = 0
            adjacent_dangerous = set()

            while queue:
                pos = queue.popleft()
                component_size += 1
                row, col = divmod(pos, W)

                for nxt in (pos - W if row > 0 else -1,
                            pos + W if row + 1 < H else -1,
                            pos - 1 if col > 0 else -1,
                            pos + 1 if col + 1 < W else -1):
                    if nxt < 0 or grid[nxt // W][nxt % W] == ord('#'):
                        continue
                    if dangerous[nxt]:
                        adjacent_dangerous.add(nxt)
                    elif not seen[nxt]:
                        seen[nxt] = 1
                        queue.append(nxt)

            answer = max(answer, component_size + len(adjacent_dangerous))

    print(answer)


