import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, m = data[0], data[1]
    inf = 10**30
    dist = [[inf] * n for _ in range(n)]

    for i in range(n):
        dist[i][i] = 0

    idx = 2
    for _ in range(m):
        u, v, w = data[idx] - 1, data[idx + 1] - 1, data[idx + 2]
        idx += 3
        dist[u][v] = w

    # Shortest paths between every pair of vertices.
    for k in range(n):
        for i in range(n):
            if dist[i][k] == inf:
                continue
            for j in range(n):
                if dist[k][j] != inf:
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    # dp[mask][v]: minimum cost of a walk visiting the vertices in mask
    # and ending at v.
    size = 1 << n
    dp = [[inf] * n for _ in range(size)]
    for v in range(n):
        dp[1 << v][v] = 0

    for mask in range(size):
        for u in range(n):
            if dp[mask][u] == inf:
                continue
            for v in range(n):
                if mask & (1 << v):
                    continue
                path_cost = dist[u][v]
                if path_cost != inf:
                    new_mask = mask | (1 << v)
                    dp[new_mask][v] = min(
                        dp[new_mask][v], dp[mask][u] + path_cost
                    )

    answer = min(dp[size - 1])
    print(answer if answer != inf else "No")

solve()
