def numberOfBeautifulIntegers(self, low: int, high: int, k: int) -> int:
    from functools import lru_cache

    def count_up_to(limit: int) -> int:
        if limit <= 0:
            return 0

        digits = list(map(int, str(limit)))

        @lru_cache(None)
        def dp(pos: int, balance: int, remainder: int, started: bool, tight: bool) -> int:
            if pos == len(digits):
                return int(started and balance == 0 and remainder == 0)

            upper = digits[pos] if tight else 9
            total = 0

            for digit in range(upper + 1):
                next_tight = tight and digit == upper
                next_started = started or digit != 0

                if not next_started:
                    total += dp(pos + 1, balance, remainder, False, next_tight)
                else:
                    next_balance = balance + (1 if digit % 2 == 0 else -1)
                    next_remainder = (remainder * 10 + digit) % k
                    total += dp(
                        pos + 1,
                        next_balance,
                        next_remainder,
                        True,
                        next_tight,
                    )

            return total

        return dp(0, 0, 0, False, True)

    return count_up_to(high) - count_up_to(low - 1)

