import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    graph = [[] for _ in range(n)]

    pos = 1
    for _ in range(n - 1):
        u = data[pos] - 1
        v = data[pos + 1] - 1
        pos += 2
        graph[u].append(v)
        graph[v].append(u)

    # Root the tree iteratively.
    parent = [-1] * n
    order = [0]
    for v in order:
        for w in graph[v]:
            if w != parent[v]:
                parent[w] = v
                order.append(w)

    children = [[] for _ in range(n)]
    for v in range(1, n):
        children[parent[v]].append(v)

    # A center is selected (1), or a star leaf/connector vertex (0).
    # For a non-center vertex, exactly one neighbor must be a center.
    # Vertices of degree >= 3 must be centers.
    #
    # dp[v][choice][parent_choice] indicates whether the subtree is feasible.
    dp = [[[False, False] for _ in range(2)] for _ in range(n)]

    for v in reversed(order):
        deg = len(graph[v])
        for choice in (0, 1):
            if choice == 1 and deg < 2:
                continue
            if choice == 0 and deg >= 3:
                continue

            for parent_choice in (0, 1):
                if v == 0 and parent_choice != 0:
                    continue

                # Center vertices have no center neighbors.
                # Non-centers have exactly one center neighbor.
                target = 0 if choice == 1 else 1
                needed_from_children = target - parent_choice
                if needed_from_children < 0:
                    continue

                possible = [False] * (len(children[v]) + 1)
                possible[0] = True
                for ch in children[v]:
                    nxt = [False] * len(possible)
                    for used in range(len(children[v])):
                        if not possible[used]:
                            continue
                        for child_choice in (0, 1):
                            if dp[ch][child_choice][choice]:
                                nxt[used + child_choice] = True
                    possible = nxt

                dp[v][choice][parent_choice] = (
                    needed_from_children < len(possible)
                    and possible[needed_from_children]
                )

    # Recover one feasible assignment.
    centers = [False] * n

    def recover(v, choice, parent_choice):
        centers[v] = bool(choice)
        target = 0 if choice == 1 else 1
        needed = target - parent_choice
        chs = children[v]

        # Build suffix feasibility tables to choose child states.
        suffix = [[False] * (len(chs) + 1) for _ in range(len(chs) + 1)]
        suffix[len(chs)][0] = True
        for i in range(len(chs) - 1, -1, -1):
            ch = chs[i]
            for c in (0, 1):
                if not dp[ch][c][choice]:
                    continue
                for total in range(len(chs) + 1):
                    if suffix[i + 1][total]:
                        suffix[i][total + c] = True

        selected = []
        remaining = needed
        for i, ch in enumerate(chs):
            chosen = None
            for c in (0, 1):
                if dp[ch][c][choice] and remaining >= c and suffix[i + 1][remaining - c]:
                    chosen = c
                    break
            selected.append(chosen)
            remaining -= chosen

        for ch, c in zip(chs, selected):
            recover(ch, c, choice)

    root_choice = 0 if dp[0][0][0] else 1
    recover(0, root_choice, 0)

    levels = sorted(len(graph[v]) for v in range(n) if centers[v])
    print(*levels)

if __name__ == "__main__":
    solve()
