            col_colors[j][color] += 1

    active_rows = [True] * H
    active_cols = [True] * W
    remaining = H * W

    def eligible(count, colors):
        return count >= 2 and max(colors) == count

    rows = {
        i for i in range(H)
        if eligible(row_count[i], row_colors[i])
    }
    cols = {
        j for j in range(W)
        if eligible(col_count[j], col_colors[j])
    }

    while rows or cols:
