def distributeCandies(self, n: int, limit: int) -> int:
    from math import comb

    total = 0
    for excluded in range(4):
        remaining = n - excluded * (limit + 1)
        if remaining >= 0:
            total += (-1) ** excluded * comb(3, excluded) * comb(remaining + 2, 2)

