        for cell in range(9):
            bit = 1 << cell
            if (red | blue) & bit:
                continue

            if takahashi_turn:
                new_red, new_blue = red | bit, blue
                if any(new_red & line == line for line in line_masks):
                    return True
            else:
                new_red, new_blue = red, blue | bit
                if any(new_blue & line == line for line in line_masks):
                    return False

            if moves == 8:
                takahashi_score = sum(values[i] for i in range(9) if new_red >> i & 1)
                aoki_score = sum(values[i] for i in range(9) if new_blue >> i & 1)
                winner_is_takahashi = takahashi_score > aoki_score
            else:
                winner_is_takahashi = takahashi_wins(new_red, new_blue)

            if takahashi_turn and winner_is_takahashi:
                return True
            if not takahashi_turn and not winner_is_takahashi:
                return False

        return not takahashi_turn

    print("Takahashi" if takahashi_wins(0, 0) else "Aoki")

