def stringIndices(wordsContainer, wordsQuery):
    trie = {}
    best_key = (len(wordsContainer[0]), 0)
    best_index = 0

    # The root represents the empty suffix.
    trie[None] = best_index

    for i, word in enumerate(wordsContainer):
        key = (len(word), i)
        if key < best_key:
            best_key = key
            best_index = i
        trie[None] = best_index

        node = trie
        for ch in reversed(word):
            if ch not in node:
                node[ch] = {None: i}
            node = node[ch]
            current = node[None]
            if key < (len(wordsContainer[current]), current):
                node[None] = i

    ans = []
    for word in wordsQuery:
        node = trie
        index = node[None]
        for ch in reversed(word):
            if ch not in node:
                break
            node = node[ch]
            index = node[None]
        ans.append(index)

    return ans

