def minimizeStringValue(self, s: str) -> str:
    import heapq

    counts = [0] * 26
    for ch in s:
        if ch != "?":
            counts[ord(ch) - ord("a")] += 1

    heap = [(counts[i], chr(ord("a") + i)) for i in range(26)]
    heapq.heapify(heap)

    replacements = []
    for ch in s:
        if ch == "?":
            count, letter = heapq.heappop(heap)
            replacements.append(letter)
            heapq.heappush(heap, (count + 1, letter))

    replacements.sort()
    result = []
    i = 0
    for ch in s:
        if ch == "?":
            result.append(replacements[i])
            i += 1
        else:
            result.append(ch)

    return "".join(result)
