def minLength(words):
    # Map (first character, last character) to the minimum length
    # of a string with those endpoints.
    dp = {(words[0][0], words[0][-1]): len(words[0])}

    for word in words[1:]:
        next_dp = {}
        for (first, last), length in dp.items():
            # Append word.
            state = (first, word[-1])
            cost = length + len(word) - (last == word[0])
            next_dp[state] = min(next_dp.get(state, float("inf")), cost)

            # Prepend word.
            state = (word[0], last)
            cost = length + len(word) - (word[-1] == first)
            next_dp[state] = min(next_dp.get(state, float("inf")), cost)

        dp = next_dp

    return min(dp.values())
