class Solution:
    def medianOfUniquenessArray(self, nums: list[int]) -> int:
        n = len(nums)
        target = (n * (n + 1) // 2 + 1) // 2

        def count_at_most(k: int) -> int:
            freq = {}
            left = 0
            count = 0

            for right, value in enumerate(nums):
                freq[value] = freq.get(value, 0) + 1

                while len(freq) > k:
                    old = nums[left]
                    freq[old] -= 1
                    if freq[old] == 0:
                        del freq[old]
                    left += 1

                count += right - left + 1

            return count

        low, high = 1, len(set(nums))
        while low < high:
            mid = (low + high) // 2
            if count_at_most(mid) >= target:
                high = mid
            else:
                low = mid + 1

        return low
