def maxStrength(nums, k):
    neg_inf = float("-inf")
    outside = [neg_inf] * (k + 1)
    inside = [neg_inf] * (k + 1)
    outside[0] = 0

    for value in nums:
        next_outside = [max(outside[j], inside[j]) for j in range(k + 1)]
        next_inside = [neg_inf] * (k + 1)

        for j in range(1, k + 1):
            coefficient = (k - j + 1) * (1 if j % 2 else -1)
            next_inside[j] = max(
                inside[j] + coefficient * value,
                outside[j - 1] + coefficient * value,
            )

        outside, inside = next_outside, next_inside

    return max(outside[k], inside[k])

