def shortest_common_superstring(a: str, b: str, c: str) -> str:
    strings = [a, b, c]
    strings = [
        s for i, s in enumerate(strings)
        if not any(i != j and s in other for j, other in enumerate(strings))
    ]

    def merge(x: str, y: str) -> str:
        if y in x:
            return x
        if x in y:
            return y

        overlap = min(len(x), len(y))
        while overlap > 0 and x[-overlap:] != y[:overlap]:
            overlap -= 1
        return x + y[overlap:]

    from itertools import permutations

    candidates = []
    for order in permutations(strings):
        result = order[0]
        for s in order[1:]:
            result = merge(result, s)
        candidates.append(result)

    return min(candidates, key=lambda s: (len(s), s))
