def maxLength(self, x: int, y: int, z: int) -> int:
    from functools import lru_cache

    # Token types: 0 = "AA", 1 = "BB", 2 = "AB"
    allowed = ((1,), (0, 2), (0, 2))

    @lru_cache(None)
    def best(a: int, b: int, c: int, last: int) -> int:
        remaining = (a, b, c)
        answer = 0

        for kind in range(3):
            if remaining[kind] == 0:
                continue
            if last != -1 and kind not in allowed[last]:
                continue

            updated = list(remaining)
            updated[kind] -= 1
            answer = max(
                answer,
                1 + best(*updated, kind)
            )

        return answer

    return 2 * best(x, y, z, -1)
