def maximumXorProduct(a: int, b: int, n: int) -> int:
    mod = 10**9 + 7
    mask = (1 << n) - 1
    x, y = a & ~mask, b & ~mask

    for bit in range(n - 1, -1, -1):
        value = 1 << bit
        if ((a >> bit) & 1) == ((b >> bit) & 1):
            x |= value
            y |= value
        elif x <= y:
            x |= value
        else:
            y |= value

    return (x * y) % mod

