def numberOfStableArrays(zero: int, one: int, limit: int) -> int:
    mod = 10**9 + 7

    # dp0[i][j] and dp1[i][j] count valid arrays ending in 0 and 1,
    # respectively, with i zeros and j ones.
    dp0 = [[0] * (one + 1) for _ in range(zero + 1)]
    dp1 = [[0] * (one + 1) for _ in range(zero + 1)]

    for i in range(1, min(zero, limit) + 1):
        dp0[i][0] = 1
    for j in range(1, min(one, limit) + 1):
        dp1[0][j] = 1

    for i in range(1, zero + 1):
        for j in range(1, one + 1):
            dp0[i][j] = dp0[i - 1][j] + dp1[i - 1][j]
            if i - limit - 1 >= 0:
                dp0[i][j] -= dp1[i - limit - 1][j]
            dp0[i][j] %= mod

            dp1[i][j] = dp0[i][j - 1] + dp1[i][j - 1]
            if j - limit - 1 >= 0:
                dp1[i][j] -= dp0[i][j - limit - 1]
            dp1[i][j] %= mod

    return (dp0[zero][one] + dp1[zero][one]) % mod

def maxStrength(nums):
    best = None
    for mask in range(1, 1 << len(nums)):
        product = 1
        for i, value in enumerate(nums):
            if mask & (1 << i):
                product *= value
        if best is None or product > best:
            best = product
    return best

