def maxSum(nums, k):
    mod = 10**9 + 7
    bit_counts = [0] * 31

    for num in nums:
        for bit in range(31):
            bit_counts[bit] += (num >> bit) & 1

    answer = 0
    for _ in range(k):
        value = 0
        for bit in range(31):
            if bit_counts[bit]:
                value |= 1 << bit
                bit_counts[bit] -= 1
        answer = (answer + value * value) % mod

    return answer
