        queue = deque([start_cell])

        while queue:
            cell = queue.popleft()
            r, c = divmod(cell, W)
            nd = dist[cell] + 1

            if r > 0:
                nxt = cell - W
                if dist[nxt] == -1 and grid[r - 1][c] != '#':
                    dist[nxt] = nd
                    queue.append(nxt)
            if r + 1 < H:
                nxt = cell + W
                if dist[nxt] == -1 and grid[r + 1][c] != '#':
