    n = len(nums)
    groups = {}

    for i, value in enumerate(nums, start=1):
        x = i
        kernel = 1
        prime = 2

        while prime * prime <= x:
            if x % prime == 0:
                odd_power = 0
                while x % prime == 0:
                    x //= prime
                    odd_power ^= 1
                if odd_power:
                    kernel *= prime
