def sumOfPowers(self, nums: list[int], k: int) -> int:
    from bisect import bisect_left

    MOD = 10**9 + 7
    values = sorted(nums)
    n = len(values)
    distances = sorted({
        values[j] - values[i]
        for i in range(n)
        for j in range(i + 1, n)
    })

    def count_with_min_gap_at_least(gap):
        # dp[r][j]: number of valid subsequences of length r ending at j.
        dp = [[0] * n for _ in range(k + 1)]
        dp[1] = [1] * n

        for r in range(2, k + 1):
            prefix = [0] * (n + 1)
            for i in range(n):
                prefix[i + 1] = prefix[i] + dp[r - 1][i]

            for j in range(n):
                limit = bisect_left(values, values[j] - gap, 0, j)
                dp[r][j] = prefix[limit]

        return sum(dp[k]) % MOD

    answer = 0
    previous = 0
    for gap in distances:
        count = count_with_min_gap_at_least(gap)
        answer = (answer + (gap - previous) * count) % MOD
        previous = gap

    return answer

