    n = len(word)
    total = 0
    start = 0

    while start < n:
        end = start + 1
        while end < n and abs(ord(word[end]) - ord(word[end - 1])) <= 2:
            end += 1

        for distinct in range(1, 27):
            window_size = distinct * k
            if window_size > end - start:
                break

            counts = [0] * 26
            exactly_k = 0

            for i in range(start, end):
                entering = ord(word[i]) - ord("a")
                if counts[entering] == k:
                    exactly_k -= 1
                counts[entering] += 1
                if counts[entering] == k:
                    exactly_k += 1

                if i >= start + window_size:
                    leaving = ord(word[i - window_size]) - ord("a")
                    if counts[leaving] == k:
                        exactly_k -= 1
                    counts[leaving] -= 1
                    if counts[leaving] == k:
                        exactly_k += 1

                if i - start + 1 >= window_size and exactly_k == distinct:
                    total += 1

        start = end

    return total

