from functools import lru_cache

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N, H, W = data[0], data[1], data[2]
    tiles = [(data[i], data[i + 1]) for i in range(3, len(data), 2)]

    full = (1 << (H * W)) - 1

    @lru_cache(None)
    def can_fill(occupied, used):
        if occupied == full:
            return True

        # The first uncovered cell in row-major order must be the
        # top-left cell of the next tile placed.
        remaining = full ^ occupied
        first_bit = remaining & -remaining
        pos = first_bit.bit_length() - 1
        row, col = divmod(pos, W)

        for i, (a, b) in enumerate(tiles):
            if used & (1 << i):
                continue

            for height, width in {(a, b), (b, a)}:
                if row + height > H or col + width > W:
                    continue

                rectangle = 0
                for r in range(row, row + height):
                    rectangle |= ((1 << width) - 1) << (r * W + col)

                if rectangle & occupied == 0:
                    if can_fill(occupied | rectangle, used | (1 << i)):
                        return True

        return False

    print("Yes" if can_fill(0, 0) else "No")

