def numberOfPowerfulInt(start: int, finish: int, limit: int, s: str) -> int:
    suffix = int(s)
    place = 10 ** len(s)

    def count_prefixes_at_most(x: int) -> int:
        """Count nonnegative integers <= x whose digits are all <= limit."""
        if x < 0:
            return 0

        digits = list(map(int, str(x)))
        total = 0

        for length in range(1, len(digits)):
            total += limit * (limit + 1) ** (length - 1)

        for i, digit in enumerate(digits):
            remaining = len(digits) - i - 1
            allowed = min(digit, limit + 1)
            total += allowed * (limit + 1) ** remaining

            if digit > limit:
                return total

        return total + 1  # Include x itself.

    low_prefix = max(0, (start - suffix + place - 1) // place)
    high_prefix = (finish - suffix) // place

    if low_prefix > high_prefix:
        return 0

    return count_prefixes_at_most(high_prefix) - count_prefixes_at_most(low_prefix - 1)

