def minimumOperations(self, x: int, y: int) -> int:
    from collections import deque

    limit = x + abs(x - y)
    queue = deque([(x, 0)])
    visited = {x}

    while queue:
        value, steps = queue.popleft()
        if value == y:
            return steps

        neighbors = [value - 1, value + 1]
        if value % 5 == 0:
            neighbors.append(value // 5)
        if value % 11 == 0:
            neighbors.append(value // 11)

        for nxt in neighbors:
            if 1 <= nxt <= limit and nxt not in visited:
                visited.add(nxt)
                queue.append((nxt, steps + 1))
