            for multiple in range(p * p, max_num + 1, p):
                if spf[multiple] == multiple:
                    spf[multiple] = p

    parent = list(range(n))
    size = [1] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]

    prime_owner = {}
    for i, value in enumerate(nums):
        while value > 1:
            prime = spf[value]
            if prime in prime_owner:
                union(i, prime_owner[prime])
            else:
                prime_owner[prime] = i
            while value % prime == 0:
                value //= prime

    root = find(0)
