def specialPerm(nums):
    MOD = 10**9 + 7
    n = len(nums)
    size = 1 << n
    dp = [[0] * n for _ in range(size)]

    for i in range(n):
        dp[1 << i][i] = 1

    for mask in range(size):
        for last in range(n):
            ways = dp[mask][last]
            if ways == 0:
                continue

            for nxt in range(n):
                if mask & (1 << nxt):
                    continue
                if nums[last] % nums[nxt] == 0 or nums[nxt] % nums[last] == 0:
                    next_mask = mask | (1 << nxt)
                    dp[next_mask][nxt] = (dp[next_mask][nxt] + ways) % MOD

    return sum(dp[size - 1]) % MOD
